import{_ as e,o,c as n,a2 as a}from"./chunks/framework.CCZdR_Jo.js";const r="/aibutler/docs-versions/v1.1.3/img/en/first-run-1.png",s="/aibutler/docs-versions/v1.1.3/img/en/first-run-2.png",m=JSON.parse('{"title":"Quickstart","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/quickstart.md","filePath":"en/guide/quickstart.md"}'),i={name:"en/guide/quickstart.md"};function l(d,t,c,u,h,p){return o(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="quickstart" tabindex="-1">Quickstart <a class="header-anchor" href="#quickstart" aria-label="Permalink to &quot;Quickstart&quot;">​</a></h1><p>From downloading it to saying your first word to your persona takes about ten minutes.</p><h2 id="_1-download-the-installer" tabindex="-1">1. Download the installer <a class="header-anchor" href="#_1-download-the-installer" aria-label="Permalink to &quot;1. Download the installer&quot;">​</a></h2><p>Go to the <a href="https://github.com/fantasyxxj/aibutler/releases" target="_blank" rel="noreferrer">Releases page</a> and download the latest version:</p><table tabindex="0"><thead><tr><th>Your computer</th><th>Download</th></tr></thead><tbody><tr><td>Mac (M1 / M2 / M3 / M4 chip)</td><td><code>aibutler-&lt;version&gt;-arm64.dmg</code></td></tr><tr><td>Mac (Intel chip)</td><td><code>aibutler-&lt;version&gt;-x64.dmg</code></td></tr><tr><td>Windows</td><td><code>aibutler-&lt;version&gt;-setup.exe</code></td></tr></tbody></table><p>Mac needs macOS 11 or later. Not sure which chip you have? Click the Apple menu in the top-left corner → <strong>About This Mac</strong>, and check the <strong>Chip</strong> or <strong>Processor</strong> line.</p><h2 id="_2-install" tabindex="-1">2. Install <a class="header-anchor" href="#_2-install" aria-label="Permalink to &quot;2. Install&quot;">​</a></h2><h3 id="mac" tabindex="-1">Mac <a class="header-anchor" href="#mac" aria-label="Permalink to &quot;Mac&quot;">​</a></h3><ol><li>Double-click the dmg and drag the app (its name on disk is <strong>全能管家</strong>, Chinese for &quot;aibutler&quot;) into the <strong>Applications</strong> folder.</li><li>The first time you open it, macOS asks whether you are sure you want to open an app downloaded from the internet. Click <strong>Open</strong>. The app is signed and notarized by Apple, so nothing else is needed.</li></ol><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><p>Double-click <code>setup.exe</code> to install. If you see &quot;Windows protected your PC,&quot; click <strong>More info</strong> → <strong>Run anyway</strong>.</p><h2 id="_3-first-launch-connect-an-ai" tabindex="-1">3. First launch: connect an AI <a class="header-anchor" href="#_3-first-launch-connect-an-ai" aria-label="Permalink to &quot;3. First launch: connect an AI&quot;">​</a></h2><p>The first time you open it, you&#39;ll see a two-step setup.</p><p><img src="'+r+'" alt="Step 1: connect an AI first"></p><p><strong>Step 1, &quot;Connect an AI first&quot;:</strong> your persona needs an AI model before it can talk, so pick whichever you have:</p><ul><li><strong>API key</strong> (selected by default): works with Anthropic, OpenAI, Chinese model providers and gateways. Click <strong>Add a key</strong>; System Settings opens on <strong>Model providers</strong>. Click <strong>+ Add one</strong>, then click your provider (Qwen, DeepSeek, Kimi…) — the address is filled in for you, you only paste the key (see <a href="/aibutler/docs-versions/v1.1.3/en/guide/models.html">Connecting Models</a>).</li><li><strong>Claude subscription</strong>: pick this if you have a Claude Pro / Max subscription. Click <strong>Turn on</strong> — it first downloads Claude&#39;s components (about 110 MB) — restart once that&#39;s done, then click <strong>Log in to Claude</strong> and sign in once.</li></ul><p>You can switch the interface language in the top-right corner. Once you&#39;re set, click <strong>Next</strong>.</p><p><strong>Step 2, &quot;Give it a name&quot;:</strong> this is your first persona — it&#39;s called &quot;Butler&quot; by default, but you can rename it and pick an avatar.</p><p>With a key, it then asks <strong>How capable?</strong> — four tiers, <strong>Top · pricey</strong>, <strong>Strong</strong>, <strong>Everyday · recommended</strong> and <strong>Budget</strong>; stronger costs more. Click one and the app tests your key on the spot to find a model in that tier, and tells you which one it will use. If the tier doesn&#39;t work on your key, it says why (no quota, model not enabled on your account…) and offers <strong>Try a cheaper tier</strong>. To choose the model yourself, open <strong>Pick a model myself</strong>. Click <strong>Create and start</strong>.</p><p><img src="'+s+'" alt="Step 2: give it a name"></p><div class="tip custom-block"><p class="custom-block-title">Two items under &quot;Advanced&quot;</p><p>You usually don&#39;t need to touch <strong>Engine</strong> or <strong>Persona files go in</strong>. A persona&#39;s file location can&#39;t be changed once it&#39;s created — if you want it on a different drive, click <strong>Change location</strong> before creating it.</p></div><h2 id="_4-say-your-first-word" tabindex="-1">4. Say your first word <a class="header-anchor" href="#_4-say-your-first-word" aria-label="Permalink to &quot;4. Say your first word&quot;">​</a></h2><p>Once it&#39;s created, the persona spends a minute or two getting to know itself, then greets you first: who it is, what it can do for you, and what you&#39;d like it to focus on. Just answer it.</p><p>When you can&#39;t think of what to ask, tap one of the buttons above the input box (such as &quot;Remind me on time&quot; or &quot;Look it up and compare&quot;) — tapping sends it for you. Or say anything, for example:</p><blockquote><p>Hi, I&#39;m Wang. I work in design — from now on, help me keep an eye on things at work.</p></blockquote><p>It will remember what you tell it and pick up from there next time. From then on it speaks up once a day, and the first time you talk to it each day it mentions one thing that is due soon or unfinished after answering you. A few things you can just ask it directly:</p><ul><li>&quot;What can you help me with?&quot;</li><li>&quot;I&#39;d like to reach you from my phone too — how do I set that up?&quot;</li><li>&quot;Build me a small expense-tracking tool.&quot;</li></ul><h2 id="_5-create-more-personas" tabindex="-1">5. Create more personas <a class="header-anchor" href="#_5-create-more-personas" aria-label="Permalink to &quot;5. Create more personas&quot;">​</a></h2><p>Click <strong>Personas ▾</strong> at the top of the window and choose <strong>+ New persona…</strong>. The quickest way is to write what it&#39;s for in <strong>One-line persona</strong> at the top and click <strong>Ask the butler to build it</strong>; or fill in a name yourself; with a key you pick a <strong>How capable?</strong> tier here too. Click <strong>Create and open</strong>. Each persona has its own name, memory, and model, and they don&#39;t interfere with each other — for example, one to handle work and one to help your kid study.</p><p>The same menu&#39;s <strong>⚙ Manage personas…</strong> opens the Personas window: each persona card&#39;s <strong>⋯</strong> menu lets you <strong>Export</strong> it, and <strong>Import from file…</strong> below lets you load an exported persona back in.</p><h2 id="running-into-trouble" tabindex="-1">Running into trouble <a class="header-anchor" href="#running-into-trouble" aria-label="Permalink to &quot;Running into trouble&quot;">​</a></h2><p>Ask your persona first. If it can&#39;t connect to a model or won&#39;t talk, see the FAQ in <a href="/aibutler/docs-versions/v1.1.3/en/guide/models.html">Connecting Models</a>.</p>',32)])])}const f=e(i,[["render",l]]);export{m as __pageData,f as default};
